  "project-search": {"id":"project-search","stage":1,"title":"实战二：异步搜索","mins":34,"summary":"处理真实世界的异步：加载、空结果、错误，以及最容易被忽略的竞态问题。","goals":["能为异步界面设计一个 status 字段，覆盖空闲、加载中、成功、空结果、出错","能解释竞态：后发出的请求先返回时，旧结果为什么会覆盖新结果","能用 effect 清理函数里的 ignore 标记修复竞态","能把请求逻辑抽成自定义 Hook（例如 useUserSearch）"],"quizAnswers":[1,1],"nCheck":2,"hasExercise":true,"nDrills":0,"drillTitles":[],"nPlays":0},
