  "tanstack-query": {"id":"tanstack-query","stage":4,"title":"数据请求：TanStack Query","mins":56,"localMins":60,"summary":"把“服务端状态”交给专业工具：缓存、去重、后台刷新、乐观更新。","goals":["能写出 useQuery：queryKey 包含查询用到的每个变量，按加载中、出错、成功渲染，并区分 status 和 fetchStatus","能预测 staleTime 不同时切回页面会不会发请求，以及两个组件用同一个 queryKey 时发出几次请求","能用 useMutation 加 invalidateQueries，在修改数据后刷新列表","能用 keepPreviousData 做分页，用 useInfiniteQuery 做“加载更多”，并说明 getNextPageParam 返回什么值表示没有下一页"],"quizAnswers":[1,1,1,0],"nCheck":8,"hasExercise":true,"nDrills":0,"drillTitles":[],"nPlays":9},
