  "use-effect": {"id":"use-effect","stage":1,"title":"useEffect 与副作用","mins":28,"summary":"让组件与外部世界同步：定时器、网络请求、订阅、修改标题。","goals":["能说出 effect 的用途：让组件与外部系统保持同步","能根据 effect 读到的值写出依赖数组，并预测它什么时候重新同步","能写出清理函数，停止上一次的同步","能判断一个需求该用 effect，还是该在渲染时计算或写进事件处理函数"],"quizAnswers":[1,0,1,1,1],"nCheck":3,"hasExercise":true,"nDrills":3,"drillTitles":["订阅按键事件：加上清理，再修掉旧的 count","依赖数组漏了 room：房间换了，连接没跟着换","不需要 effect：把派生数据挪到渲染中"],"drillMins":11,"nPlays":4},
